from taf.config.testline import RealEnb, PrismaEnb, LTEEmuEnb, DocomoEnb


class EnbAttrs(object):

    def __init__(self, enbs):
        self.enbs = enbs

    def has_enb(self):
        if self.enbs is not None:
            return len(self.enbs) > 0
        return False

    def get_x2_link_addr(self):
        if self.enbs is not None:
            enb = self.enbs[0]
        else:
            raise AttributeError('No enb in testline object.')
        if isinstance(enb, RealEnb):
            return enb.x2_link_addr
        elif isinstance(enb, PrismaEnb):
            return enb.tstm_x2_ssh_connection_details.addr
        else:
            return enb.default_ssh_connection_details.addr

    def get_real_enbs(self):
        if self.enbs is None:
            raise AttributeError('No enb in testline object.')
        return [enb for enb in self.enbs if isinstance(enb, RealEnb)]

    def get_prisma_enbs(self):
        if self.enbs is None:
            raise AttributeError('No enb in testline object.')
        return [enb for enb in self.enbs if isinstance(enb, PrismaEnb)]

    def get_lteemu_enbs(self):
        if self.enbs is None:
            raise AttributeError('No enb in testline object.')
        return [enb for enb in self.enbs if isinstance(enb, LTEEmuEnb)]

    def get_docomo_enbs(self):
        if self.enbs is None:
            raise AttributeError('No enb in testline object.')
        return [enb for enb in self.enbs if isinstance(enb, DocomoEnb)]
